WITH report_range_source AS (SELECT '' AS subject_id,'' AS task_id,'' AS task_incarnation_id,'' AS session_id,'' AS session_incarnation_id,'' AS work_key,'summary' AS coverage_kind,g.period,c.calendar,'requested' AS calendar_basis,c.metric_kind,c.actor_id,c.actor_status,c.actor_kind,c.source,c.model,c.provider,c.agent_client,c.semantics,c.currency,c.input_tokens,c.output_tokens,c.cache_read_tokens,c.cache_write_tokens,c.reasoning_tokens,c.total_tokens,c.source_total_tokens,c.turns,c.cost_subcents,c.rate_tokens,c.input_missing,c.output_missing,c.cache_read_missing,c.cache_write_missing,c.reasoning_missing,c.total_missing,c.source_total_missing,c.turns_missing,c.cost_missing,c.rate_missing,c.token_count,c.cost_count,c.partial_count+CASE WHEN g.month_partial=1 THEN c.token_count+c.cost_count ELSE 0 END AS partial_count,c.estimated_count,c.stale_count,c.cost_basis FROM usage_daily_summaries c JOIN usage_report_calendar g ON g.period=c.usage_date AND g.full_day=1 WHERE  c.scope_id=? AND c.generation=? AND c.calendar=?
 AND c.usage_date>=(SELECT MIN(period) FROM usage_report_calendar) AND c.usage_date<=(SELECT MAX(period) FROM usage_report_calendar) UNION ALL SELECT u.subject_id,u.task_id,u.task_incarnation_id,u.session_id,u.session_incarnation_id,f.work_key,f.coverage_kind,g.period,? AS calendar,'requested' AS calendar_basis,c.metric_kind,c.actor_id,c.actor_status,c.actor_kind,c.source,c.model,c.provider,c.agent_client,c.semantics,c.currency,c.input_tokens,c.output_tokens,c.cache_read_tokens,c.cache_write_tokens,c.reasoning_tokens,c.total_tokens,c.source_total_tokens,c.turns,c.cost_subcents,c.rate_tokens,CASE WHEN c.metric_kind = 'tokens' AND c.input_tokens IS NULL THEN 1 ELSE 0 END AS input_missing,CASE WHEN c.metric_kind = 'tokens' AND c.output_tokens IS NULL THEN 1 ELSE 0 END AS output_missing,CASE WHEN c.metric_kind = 'tokens' AND c.cache_read_tokens IS NULL THEN 1 ELSE 0 END AS cache_read_missing,CASE WHEN c.metric_kind = 'tokens' AND c.cache_write_tokens IS NULL THEN 1 ELSE 0 END AS cache_write_missing,CASE WHEN c.metric_kind = 'tokens' AND c.reasoning_tokens IS NULL THEN 1 ELSE 0 END AS reasoning_missing,CASE WHEN c.metric_kind = 'tokens' AND c.total_tokens IS NULL THEN 1 ELSE 0 END AS total_missing,CASE WHEN c.metric_kind = 'tokens' AND c.source_total_tokens IS NULL THEN 1 ELSE 0 END AS source_total_missing,CASE WHEN c.metric_kind = 'tokens' AND c.turns IS NULL THEN 1 ELSE 0 END AS turns_missing,CASE WHEN c.metric_kind = 'cost' AND c.cost_subcents IS NULL THEN 1 ELSE 0 END AS cost_missing,CASE WHEN c.metric_kind = 'cost' AND c.rate_tokens IS NULL THEN 1 ELSE 0 END AS rate_missing,CASE WHEN c.metric_kind = 'tokens' THEN 1 ELSE 0 END AS token_count,CASE WHEN c.metric_kind = 'cost' THEN 1 ELSE 0 END AS cost_count,CASE WHEN c.partial <> 0 OR (g.month_partial=1) THEN 1 ELSE 0 END AS partial_count,c.estimated AS estimated_count,c.stale AS stale_count,c.cost_basis FROM usage_projection_contributions c JOIN usage_projection_applied a ON a.scope_id=c.scope_id AND a.generation=c.generation AND a.work_key=c.work_key AND a.build_id=c.build_id
 JOIN usage_canonical_facts f ON f.scope_id=c.scope_id AND f.generation=c.generation AND f.build_id=c.build_id AND f.fact_key=c.fact_key
 JOIN usage_subjects u ON u.scope_id=f.scope_id AND u.subject_id=f.subject_id  JOIN usage_report_calendar g ON c.coverage_start>=g.start_at AND c.coverage_start<g.end_at WHERE  c.scope_id=? AND c.generation=? AND c.coverage_kind='point' AND c.calendar='UTC'
 AND c.coverage_start>=(SELECT MIN(start_at) FROM usage_report_calendar) AND c.coverage_start<(SELECT MAX(end_at) FROM usage_report_calendar) AND (g.full_day=0 OR f.calendar<>?) UNION ALL SELECT u.subject_id,u.task_id,u.task_incarnation_id,u.session_id,u.session_incarnation_id,f.work_key,f.coverage_kind,c.usage_date AS period,c.calendar,CASE WHEN c.calendar=? THEN 'requested' ELSE 'source' END AS calendar_basis,c.metric_kind,c.actor_id,c.actor_status,c.actor_kind,c.source,c.model,c.provider,c.agent_client,c.semantics,c.currency,c.input_tokens,c.output_tokens,c.cache_read_tokens,c.cache_write_tokens,c.reasoning_tokens,c.total_tokens,c.source_total_tokens,c.turns,c.cost_subcents,c.rate_tokens,CASE WHEN c.metric_kind = 'tokens' AND c.input_tokens IS NULL THEN 1 ELSE 0 END AS input_missing,CASE WHEN c.metric_kind = 'tokens' AND c.output_tokens IS NULL THEN 1 ELSE 0 END AS output_missing,CASE WHEN c.metric_kind = 'tokens' AND c.cache_read_tokens IS NULL THEN 1 ELSE 0 END AS cache_read_missing,CASE WHEN c.metric_kind = 'tokens' AND c.cache_write_tokens IS NULL THEN 1 ELSE 0 END AS cache_write_missing,CASE WHEN c.metric_kind = 'tokens' AND c.reasoning_tokens IS NULL THEN 1 ELSE 0 END AS reasoning_missing,CASE WHEN c.metric_kind = 'tokens' AND c.total_tokens IS NULL THEN 1 ELSE 0 END AS total_missing,CASE WHEN c.metric_kind = 'tokens' AND c.source_total_tokens IS NULL THEN 1 ELSE 0 END AS source_total_missing,CASE WHEN c.metric_kind = 'tokens' AND c.turns IS NULL THEN 1 ELSE 0 END AS turns_missing,CASE WHEN c.metric_kind = 'cost' AND c.cost_subcents IS NULL THEN 1 ELSE 0 END AS cost_missing,CASE WHEN c.metric_kind = 'cost' AND c.rate_tokens IS NULL THEN 1 ELSE 0 END AS rate_missing,CASE WHEN c.metric_kind = 'tokens' THEN 1 ELSE 0 END AS token_count,CASE WHEN c.metric_kind = 'cost' THEN 1 ELSE 0 END AS cost_count,CASE WHEN c.partial <> 0 OR (c.calendar<>? OR c.coverage_start<? OR c.coverage_end>?) THEN 1 ELSE 0 END AS partial_count,c.estimated AS estimated_count,c.stale AS stale_count,c.cost_basis FROM usage_projection_contributions c JOIN usage_projection_applied a ON a.scope_id=c.scope_id AND a.generation=c.generation AND a.work_key=c.work_key AND a.build_id=c.build_id
 JOIN usage_canonical_facts f ON f.scope_id=c.scope_id AND f.generation=c.generation AND f.build_id=c.build_id AND f.fact_key=c.fact_key
 JOIN usage_subjects u ON u.scope_id=f.scope_id AND u.subject_id=f.subject_id  WHERE  c.scope_id=? AND c.generation=? AND c.coverage_kind IN ('calendar','interval') AND 1=1 AND c.coverage_end>? AND c.coverage_start<? AND (c.calendar<>? OR NOT EXISTS (SELECT 1 FROM usage_report_calendar g WHERE g.period=c.usage_date AND g.full_day=1))) INSERT INTO usage_report_range (subject_id,task_id,task_incarnation_id,session_id,session_incarnation_id,work_key,coverage_kind,period,calendar_basis,cost_basis,metric_kind,actor_id,actor_status,actor_kind,source,model,provider,agent_client,semantics,currency,calendar,input_tokens,output_tokens,cache_read_tokens,cache_write_tokens,reasoning_tokens,total_tokens,source_total_tokens,turns,cost_subcents,rate_tokens,input_missing,output_missing,cache_read_missing,cache_write_missing,reasoning_missing,total_missing,source_total_missing,turns_missing,cost_missing,rate_missing,token_count,cost_count,partial_count,estimated_count,stale_count)
 SELECT '','','','','','',coverage_kind,period,calendar_basis,cost_basis,metric_kind,actor_id,actor_status,actor_kind,source,model,provider,agent_client,semantics,currency,calendar,CAST(SUM(input_tokens) AS BIGINT),CAST(SUM(output_tokens) AS BIGINT),CAST(SUM(cache_read_tokens) AS BIGINT),CAST(SUM(cache_write_tokens) AS BIGINT),CAST(SUM(reasoning_tokens) AS BIGINT),CAST(SUM(total_tokens) AS BIGINT),CAST(SUM(source_total_tokens) AS BIGINT),CAST(SUM(turns) AS BIGINT),CAST(SUM(cost_subcents) AS BIGINT),CAST(SUM(rate_tokens) AS BIGINT),CAST(SUM(input_missing) AS BIGINT),CAST(SUM(output_missing) AS BIGINT),CAST(SUM(cache_read_missing) AS BIGINT),CAST(SUM(cache_write_missing) AS BIGINT),CAST(SUM(reasoning_missing) AS BIGINT),CAST(SUM(total_missing) AS BIGINT),CAST(SUM(source_total_missing) AS BIGINT),CAST(SUM(turns_missing) AS BIGINT),CAST(SUM(cost_missing) AS BIGINT),CAST(SUM(rate_missing) AS BIGINT),CAST(SUM(token_count) AS BIGINT),CAST(SUM(cost_count) AS BIGINT),CAST(SUM(partial_count) AS BIGINT),CAST(SUM(estimated_count) AS BIGINT),CAST(SUM(stale_count) AS BIGINT) FROM report_range_source GROUP BY coverage_kind,period,calendar_basis,cost_basis,metric_kind,actor_id,actor_status,actor_kind,source,model,provider,agent_client,semantics,currency,calendar;
